package persona

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
)

// Reference portfolios: what the investor a character follows, or the firm
// that carries their name, has publicly disclosed holding. They let a
// character say how a company compares with that portfolio. They are dated
// facts from public filings, not recommendations, and not a statement of what
// any person thinks today. The data is regenerated by
// scripts/refresh_reference_portfolios.py.

//go:embed data/reference_portfolios.json
var portfolioJSON []byte

// Kinds of reference portfolio.
const (
	PortfolioKind13F      = "13f"       // an SEC 13F-HR filing: long US-listed equity at a quarter end
	PortfolioKindETFDaily = "etf_daily" // a fund's published daily holdings
	PortfolioKindRules    = "rules"     // no current holdings exist; the approach's portfolio rules instead
)

// Position is one holding as disclosed.
type Position struct {
	Symbol    string   `json:"symbol"`
	Name      string   `json:"name"`
	WeightPct float64  `json:"weight_pct"` // share of the disclosed holdings, not of net worth or assets under management
	Shares    int64    `json:"shares,omitempty"`
	Change    *float64 `json:"shares_change_pct,omitempty"` // against the previous 13F; absent when unknown or new
}

// Stats describe how concentrated a portfolio is.
type Stats struct {
	Positions int     `json:"positions"`
	Top1Pct   float64 `json:"top1_pct"`
	Top5Pct   float64 `json:"top5_pct"`
	Top10Pct  float64 `json:"top10_pct"`
	HHI       int     `json:"hhi"` // Herfindahl index on a 0-10000 scale; below 150 is very diversified, above 1000 concentrated
}

// Portfolio is a reference portfolio snapshot.
type Portfolio struct {
	Persona   string     `json:"persona"`
	Kind      string     `json:"kind"`
	Filer     string     `json:"filer"`
	Form      string     `json:"form,omitempty"`
	Period    string     `json:"period"` // the date the holdings are as of
	Filed     string     `json:"filed,omitempty"`
	Accession string     `json:"accession,omitempty"`
	SourceURL string     `json:"source_url"`
	TotalUSD  float64    `json:"total_value_usd,omitempty"`
	Stats     Stats      `json:"stats"`
	Positions []Position `json:"positions"`
	Exited    []string   `json:"exited_since_previous,omitempty"`
	Notes     []string   `json:"notes"`
	Rules     []string   `json:"rules,omitempty"` // for KindRules: the portfolio rules of the approach
}

type portfolioFile struct {
	GeneratedAt string      `json:"generated_at"`
	Portfolios  []Portfolio `json:"portfolios"`
}

var (
	snapshots   = map[string]Portfolio{}
	snapshotsAt string
)

func init() {
	var f portfolioFile
	if err := json.Unmarshal(portfolioJSON, &f); err != nil {
		panic("persona: reference_portfolios.json: " + err.Error())
	}
	snapshotsAt = f.GeneratedAt
	for _, p := range f.Portfolios {
		snapshots[p.Persona] = p
	}
	for id, p := range rulePortfolios() {
		snapshots[id] = p
	}
}

// PortfolioOf returns a character's reference portfolio, or false.
func PortfolioOf(id string) (Portfolio, bool) {
	p, ok := snapshots[id]
	return p, ok
}

// Summary is the portfolio without the long position list, for catalogues.
func (p Portfolio) Summary(top int) Portfolio {
	if top >= 0 && len(p.Positions) > top {
		p.Positions = append([]Position(nil), p.Positions[:top]...)
	}
	return p
}

// Holding says how one symbol sits in a reference portfolio.
type Holding struct {
	Held      bool     `json:"held"`
	Symbol    string   `json:"symbol"`
	Name      string   `json:"name,omitempty"`
	WeightPct float64  `json:"weight_pct,omitempty"`
	Rank      int      `json:"rank,omitempty"`
	Change    *float64 `json:"shares_change_pct,omitempty"`
	Note      string   `json:"note"`
}

// Lookup finds a symbol among the portfolio's listed positions (the largest
// ones only, so "not listed" can also mean "too small to list").
func (p Portfolio) Lookup(symbol string) Holding {
	symbol = strings.ToUpper(strings.TrimSpace(symbol))
	h := Holding{Symbol: symbol}
	if p.Kind == PortfolioKindRules || len(p.Positions) == 0 {
		h.Note = "This character has no disclosed holdings to compare with; see its portfolio rules."
		return h
	}
	for i, pos := range p.Positions {
		if strings.EqualFold(pos.Symbol, symbol) && symbol != "" {
			h.Held, h.Name, h.WeightPct, h.Rank, h.Change = true, pos.Name, pos.WeightPct, i+1, pos.Change
			h.Note = fmt.Sprintf("Listed at %.2f%% of the disclosed holdings, rank %d of the %d largest, as of %s.", pos.WeightPct, i+1, len(p.Positions), p.Period)
			return h
		}
	}
	h.Note = fmt.Sprintf("Not among the %d largest disclosed positions as of %s. It may be held in a smaller amount, or not at all.", len(p.Positions), p.Period)
	return h
}

// Sector-free similarity check: how much of the portfolio's weight a list of
// symbols covers. Used to see how a candidate watchlist overlaps with it.
func (p Portfolio) Overlap(symbols []string) (coveragePct float64, matched []string) {
	want := map[string]bool{}
	for _, s := range symbols {
		want[strings.ToUpper(strings.TrimSpace(s))] = true
	}
	for _, pos := range p.Positions {
		if pos.Symbol != "" && want[strings.ToUpper(pos.Symbol)] {
			coveragePct += pos.WeightPct
			matched = append(matched, pos.Symbol)
		}
	}
	sort.Strings(matched)
	return math.Round(coveragePct*100) / 100, matched
}

// PromptLine is one compact line for a character's prompt: where its
// reference portfolio comes from, how concentrated it is and its largest
// positions, all with the date.
func (p Portfolio) PromptLine() string {
	if p.Kind == PortfolioKindRules {
		return ""
	}
	var top []string
	for i, pos := range p.Positions {
		if i == 5 {
			break
		}
		label := pos.Symbol
		if label == "" {
			label = pos.Name
		}
		top = append(top, fmt.Sprintf("%s %.1f%%", label, pos.WeightPct))
	}
	return fmt.Sprintf("%s, as of %s (%s): %d positions, top 5 = %.0f%%, top 10 = %.0f%%, largest %s.",
		p.Filer, p.Period, map[string]string{PortfolioKind13F: "SEC 13F filing", PortfolioKindETFDaily: "published daily holdings"}[p.Kind], p.Stats.Positions, p.Stats.Top5Pct, p.Stats.Top10Pct, strings.Join(top, ", "))
}

// SnapshotDate is when the data file was last generated.
func SnapshotDate() string { return snapshotsAt }
